INSERT INTO `lz_predefined` (`id`, `internal_id`, `group_id`, `lang_iso`, `invitation_manual`, `invitation_auto`, `welcome`, `welcome_call_me_back`, `website_push_manual`, `website_push_auto`, `chat_info`, `call_me_back_info`, `ticket_info`, `browser_ident`, `is_default`, `auto_welcome`, `editable`, `email_chat_transcript`, `email_ticket_responder`, `email_ticket_reply`, `queue_message`, `queue_message_time`, `subject_chat_transcript`, `subject_ticket_responder`, `subject_ticket_reply`, `email_chat_transcript_html`, `email_ticket_responder_html`, `email_ticket_reply_html`) VALUES
('604494acbb1c803dd61b0c7967397e58', '', 'publicidadcines', 'EN', 'Hello, my name is %operator_name%.<br><br>Do you need help?<br><br>Start Live-Chat now to get assistance.', 'Hello, my name is %operator_name%.<br><br>Do you need help?<br><br>Start Live-Chat now to get assistance.', 'Hello %external_name%, my name is %operator_name%, how may I help you?', 'Hello, my name is %operator_name%. Please expect my telephone call in the next few seconds. During our telephone conversation, feel free to pass me information and files through this chat.', 'Website Operator %operator_name% would like to redirect you to this URL:\r\n\r\n%target_url%', 'Website Operator %operator_name% would like to redirect you to this URL:\r\n\r\n%target_url%', '', '', '', 1, 1, 1, 1, 'Hi %external_name%,\r\n\r\nThank you for chatting with us. Please find your chat transcript below.\r\n\r\n%website_name% / %group_description%\r\n\r\nDate: %localdate%\r\n-------------------------------------------------------------\r\nName: %external_name%\r\nEmail: %external_email%\r\nTopic: %question%\r\n\r\nChat reference number: %chat_id%\r\n-------------------------------------------------------------\r\n%transcript%\r\n-------------------------------------------------------------\r\n\r\nWould you like to give feedback?\r\n%feedback_link%', 'Hi %external_name%,\r\n\r\nThank you for getting in touch with us. \r\n\r\nWe have received your message and will be responding to your enquiry as soon as possible.\r\n\r\n-------------------------------------------------------------\r\nDate: %localdate%\r\n-------------------------------------------------------------\r\nName: %external_name%\r\nEmail: %external_email%\r\nGroup: %group_description%\r\n-------------------------------------------------------------\r\n%mailtext%\r\n\r\n%ticket_hash%', '%mailtext%\r\n\r\n-------------------------------------------------------------\r\nPrevious Message:\r\n\r\n%quote%\r\n-------------------------------------------------------------\r\n\r\nWould you like to give feedback?\r\n%feedback_link%', '', 120, '%website_name% - Chat Transcript', '%ticket_hash% %website_name% - Your message', '%ticket_hash% %website_name% - Your message', '', '', ''),
('7f84dbc45e4bbb3648de64d46eac005c', '24a41cb', '', 'AA', 'Hello, my name is %operator_name%.<br><br>Do you need help?<br><br>Start Live-Chat now to get assistance.', 'Hello, my name is %operator_name%.<br><br>Do you need help?<br><br>Start Live-Chat now to get assistance.', 'Hola %external_name%, mi nombre es %operator_name%, en que puedo ayudarte?', 'Hello, my name is %operator_name%. Please expect my telephone call in the next few seconds. During our telephone conversation, feel free to pass me information and files through this chat.', 'Website Operator %operator_name% would like to redirect you to this URL:\r\n\r\n%target_url%', 'Website Operator %operator_name% would like to redirect you to this URL:\r\n\r\n%target_url%', '', '', '', 1, 1, 1, 0, '', '', '', '', 120, '', '', '', '', '', ''),
('d6baa3961c5366a1cbec4488ff152035', '', 'publicidadcines', 'DE', 'Guten Tag, mein Name ist %operator_name%. Benötigen Sie Hilfe? Gerne berate ich Sie in einem Live-Chat.', 'Guten Tag, mein Name ist %operator_name%. Benötigen Sie Hilfe? Gerne berate ich Sie in einem Live-Chat.', 'Guten Tag %external_name%, mein Name ist %operator_name%. Wie kann ich Ihnen helfen?', 'Guten Tag, meine Name ist %operator_name%. Sie werden in den nächsten Sekunden einen Anruf von mir erhalten. Während unseres Telefonats können Sie mir bei Bedarf Informationen und Dateien auch über diesen Chat zukommen lassen.', 'Ein Betreuer dieser Webseite (%operator_name%) möchte Sie auf einen anderen Bereich weiterleiten:\r\n\r\n%target_url%', 'Ein Betreuer dieser Webseite (%operator_name%) möchte Sie auf einen anderen Bereich weiterleiten:\r\n\r\n%target_url%', '', '', '', 1, 0, 1, 1, 'Guten Tag %external_name%,\r\n\r\nvielen Dank für unser Gespräch per Chat. Eine Mitschrift erhalten Sie mit dieser E-Mail.\r\n\r\n%website_name% / %group_description%\r\n\r\nDatum: %localdate%\r\n-------------------------------------------------------------\r\nName: %external_name%\r\nE-Mail: %external_email%\r\nBetreff: %question%\r\n\r\nChat Referenz-Code: %chat_id%\r\n-------------------------------------------------------------\r\n%transcript%\r\n-------------------------------------------------------------\r\n\r\nSind Sie zufrieden? Bewerten Sie uns:\r\n%feedback_link%', 'Guten Tag %external_name%,\r\n\r\nvielen Dank für Ihre Anfrage. \r\n\r\nWir haben Ihre Nachricht erhalten und werden uns in Kürze mit Ihnen in Verbindung setzen.\r\n\r\n-------------------------------------------------------------\r\nDatum: %localdate%\r\n-------------------------------------------------------------\r\nName: %external_name%\r\nE-Mail: %external_email%\r\nGruppe: %group_description%\r\n-------------------------------------------------------------\r\n%mailtext%\r\n\r\n%ticket_hash%', '%mailtext%\r\n-------------------------------------------------------------\r\nVorherige Nachricht:\r\n\r\n%quote%\r\n-------------------------------------------------------------\r\n\r\nSind Sie zufrieden? Bewerten Sie uns:\r\n%feedback_link%', '', 120, '%website_name% - Mitschrift Ihres Chats', '%ticket_hash% %website_name% - Ihre Nachricht', '%ticket_hash% %website_name% - Ihre Nachricht', '', '', '');
